LL Cnt[N];
int main() {
#ifndef ONLINE_JUDGE
	freopen("in.txt","r",stdin);
#endif
	ios::sync_with_stdio(false);
	cin.tie(0);
	LL n,x,mod;
	cin>>n>>x>>mod;
	for(int i=1; i<=n; ++i) {
		int tmp=x%mod;
		Cnt[i]=Cnt[i-1]+tmp;
		if(flag[tmp]) {
			int &pos=flag[tmp],len=i-pos;
